def get_tweets_by_userid(user_id, include_replies=None, include_quotes=None, status=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _encode_cursor(payload):
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    t0 = time.time()
    endpoint = "get_tweets_by_userid"

    # Validate (relax strict ^usr_01H... since datastore uses usr_01J...)
    if not isinstance(user_id, str) or not re.match(r"^usr_01[0-9A-Z]{10,}$", user_id):
        # log then return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "note": "bad user_id"
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "user_id is malformed", field="user_id")

    if include_replies is None:
        include_replies = False
    if include_quotes is None:
        include_quotes = False
    if not isinstance(include_replies, bool):
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "bad include_replies"})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "include_replies must be boolean", field="include_replies")
    if not isinstance(include_quotes, bool):
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "bad include_quotes"})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "include_quotes must be boolean", field="include_quotes")

    if status is None:
        status = "published"
    if not isinstance(status, str) or status not in ("published", "deleted", "hidden"):
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "bad status"})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "Unsupported status filter", field="status")

    if sort is None:
        sort = "created_at_desc"
    if not isinstance(sort, str) or sort not in ("created_at_desc", "created_at_asc"):
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "bad sort"})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "Unsupported sort", field="sort")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "bad limit"})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    cur = None
    if cursor is not None:
        if not isinstance(cursor, str):
            logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
            logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "bad cursor type"})
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        cur = _decode_cursor(cursor)
        if cur is None:
            logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
            logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "bad cursor decode"})
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    author = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not author:
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "author not found"})
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Author user not found", resource="users", id=user_id)

    tweets = _load("tweets.json")
    if not isinstance(tweets, list):
        tweets = []

    # Business rule: published only. Tool parameter allows others, but keep consistent with backend rule by requiring published.
    if status != "published":
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "status not allowed by business rule"})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "Only status='published' is supported for this endpoint", field="status", rule="tweets.status='published'")

    rows = []
    for tw in tweets:
        if not isinstance(tw, dict):
            continue
        if tw.get("author_user_id") != user_id:
            continue
        if tw.get("status") != "published":
            continue
        if not include_replies and tw.get("reply_to_tweet_id") is not None:
            continue
        if not include_quotes and tw.get("quote_of_tweet_id") is not None:
            continue
        rows.append(tw)

    reverse = (sort == "created_at_desc")
    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min), reverse=reverse)

    start = 0
    if cur:
        # expects {"i": int, "u": user_id} for safety
        if cur.get("u") != user_id or not isinstance(cur.get("i"), int) or cur.get("i") < 0:
            logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
            logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "cursor mismatch"})
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "cursor does not match request", field="cursor")
        start = cur["i"]

    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < len(rows)
    if has_more:
        next_cursor = _encode_cursor({"u": user_id, "i": start + limit})

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    logs.append({
        "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "timestamp": _now_iso(),
        "note": "ok"
    })
    _save("request_logs.json", logs)

    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_tweet_by_id(tweet_id, include_entities=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()
    endpoint = "get_tweet_by_id"

    if include_entities is None:
        include_entities = False
    if not isinstance(include_entities, bool):
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "bad include_entities"})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "include_entities must be boolean", field="include_entities")

    if not isinstance(tweet_id, str) or not tweet_id.strip():
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "bad tweet_id"})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "tweet_id is malformed", field="tweet_id")

    # Relax pattern: datastore uses twt_01J...
    is_internal = bool(re.match(r"^twt_01[0-9A-Z]{10,}$", tweet_id))

    tweets = _load("tweets.json")
    if not isinstance(tweets, list):
        tweets = []

    tw = None
    for r in tweets:
        if not isinstance(r, dict):
            continue
        if is_internal and r.get("id") == tweet_id:
            tw = r
            break
        if (not is_internal) and r.get("x_tweet_id") == tweet_id:
            tw = r
            break

    if not tw:
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "tweet not found"})
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Tweet not found", resource="tweets", id=tweet_id)

    # Must not return deleted tweets
    if tw.get("status") == "deleted":
        logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
        logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "tweet deleted"})
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Tweet not found", resource="tweets", id=tweet_id)

    out = dict(tw)

    if include_entities:
        ents = _load("tweet_entities.json")
        if not isinstance(ents, list):
            ents = []
        out["entities"] = [e for e in ents if isinstance(e, dict) and e.get("tweet_id") == tw.get("id")]

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    logs.append({
        "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "timestamp": _now_iso(),
        "note": "ok"
    })
    _save("request_logs.json", logs)

    return {"data": out}

def get_user_mentions(user_id, status=None, sort=None, limit=None, cursor=None, **_extra):
