    ents = _load("tweet_entities.json")
    if not isinstance(ents, list):
        ents = []

    mention_tweet_ids = set()
    for e in ents:
        if not isinstance(e, dict):
            continue
        if e.get("entity_type") == "mention" and e.get("mentioned_user_id") == user_id and e.get("tweet_id"):
            mention_tweet_ids.add(e.get("tweet_id"))

    tweets = _load("tweets.json")
    if not isinstance(tweets, list):
        tweets = []

    rows = []
    for tw in tweets:
        if not isinstance(tw, dict):
            continue
        if tw.get("id") not in mention_tweet_ids:
            continue
        if tw.get("status") != "published":
            continue
        rows.append(tw)

    reverse = (sort == "created_at_desc")
    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min), reverse=reverse)

    start = 0
