            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "cursor does not match request", field="cursor")
        start = cur["i"]

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = _encode_cursor({"u": user_id, "i": start + limit}) if has_more else None

    logs = _load("request_logs.json"); logs = logs if isinstance(logs, list) else []
    logs.append({"id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}", "endpoint": endpoint, "status": "OK", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "note": "ok"})
    _save("request_logs.json", logs)

    return {"data": page, "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def quote_tweet(author_user_id, quote_of_tweet_id, text, lang=None, source=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_01J" + "".join(secrets.choice(alphabet) for _ in range(16))

    def _log(status, note=None, actor_user_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "quote_tweet",
            "actor_user_id": actor_user_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "note": note
        })
        _save("request_logs.json", logs)

    t0 = time.time()

