def like_tweet(actor_user_id, tweet_id, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_01J" + "".join(secrets.choice(alphabet) for _ in range(16))

    def _log(status, note=None, actor=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "like_tweet",
            "actor_user_id": actor,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "note": note
        })
        _save("request_logs.json", logs)

    t0 = time.time()

    if not isinstance(actor_user_id, str) or not re.match(r"^usr_01[0-9A-Z]{10,}$", actor_user_id):
        _log("VALIDATION_ERROR", "actor_user_id malformed")
        return _err("VALIDATION_ERROR", "actor_user_id is malformed", field="actor_user_id")
    if not isinstance(tweet_id, str) or not re.match(r"^twt_01[0-9A-Z]{10,}$", tweet_id):
        _log("VALIDATION_ERROR", "tweet_id malformed", actor=actor_user_id)
        return _err("VALIDATION_ERROR", "tweet_id is malformed", field="tweet_id")

    users = _load("users.json"); users = users if isinstance(users, list) else []
    tweets = _load("tweets.json"); tweets = tweets if isinstance(tweets, list) else []
    edges = _load("social_edges.json"); edges = edges if isinstance(edges, list) else []

    actor = next((u for u in users if isinstance(u, dict) and u.get("id") == actor_user_id), None)
    if not actor:
        _log("NOT_FOUND", "actor not found", actor=actor_user_id)
        return _err("NOT_FOUND", "Actor user not found", resource="users", id=actor_user_id)
    if actor.get("status") != "active":
        _log("UNAUTHORIZED", "actor not active", actor=actor_user_id)
        return _err("UNAUTHORIZED", "User is not allowed to perform this action", reason="user_not_active")

    tw = next((t for t in tweets if isinstance(t, dict) and t.get("id") == tweet_id), None)
    if not tw:
        _log("NOT_FOUND", "tweet not found", actor=actor_user_id)
        return _err("NOT_FOUND", "Tweet not found", resource="tweets", id=tweet_id)
    if tw.get("status") != "published":
        _log("CONFLICT", "tweet not likeable", actor=actor_user_id)
        return _err("CONFLICT", "Tweet is not likeable due to its current status", rule="tweets.status must be 'published'")

    now = _now_iso()

    edge = None
    for e in edges:
        if not isinstance(e, dict):
            continue
        if e.get("edge_type") == "like" and e.get("actor_user_id") == actor_user_id and e.get("target_tweet_id") == tweet_id:
            edge = e
            break

    # Ensure public_metrics exists
    pm = tw.get("public_metrics")
    if not isinstance(pm, dict):
        pm = {"reply_count": 0, "retweet_count": 0, "like_count": 0, "quote_count": 0, "impression_count": 0}
        tw["public_metrics"] = pm
    if not isinstance(pm.get("like_count"), int) or pm.get("like_count") < 0:
        pm["like_count"] = 0

    if edge:
        if edge.get("status") == "active":
            # idempotent re-like
            _log("OK", "already liked", actor=actor_user_id)
            return {"data": {"like": edge, "tweet": tw}}
        # transition revoked -> active
        edge["status"] = "active"
        edge["updated_at"] = now
        # increment exactly once on transition
        pm["like_count"] = pm.get("like_count", 0) + 1
        tw["updated_at"] = now
        _save("social_edges.json", edges)
        _save("tweets.json", tweets)
        _log("OK", "reactivated", actor=actor_user_id)
        return {"data": {"like": edge, "tweet": tw}}

    # create new edge
    edge = {
        "id": _gen_id("edg"),
        "edge_type": "like",
        "actor_user_id": actor_user_id,
        "target_user_id": None,
        "target_tweet_id": tweet_id,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    edges.append(edge)
    pm["like_count"] = pm.get("like_count", 0) + 1
    tw["updated_at"] = now

    _save("social_edges.json", edges)
