def follow_user(actor_user_id, target_user_id, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_01J" + "".join(secrets.choice(alphabet) for _ in range(16))

    def _log(status, note=None, actor=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "follow_user",
            "actor_user_id": actor,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "note": note
        })
        _save("request_logs.json", logs)

    t0 = time.time()

    if not isinstance(actor_user_id, str) or not re.match(r"^usr_01[0-9A-Z]{10,}$", actor_user_id):
        _log("VALIDATION_ERROR", "actor_user_id malformed")
        return _err("VALIDATION_ERROR", "actor_user_id is malformed", field="actor_user_id")
    if not isinstance(target_user_id, str) or not re.match(r"^usr_01[0-9A-Z]{10,}$", target_user_id):
        _log("VALIDATION_ERROR", "target_user_id malformed", actor=actor_user_id)
        return _err("VALIDATION_ERROR", "target_user_id is malformed", field="target_user_id")
    if actor_user_id == target_user_id:
        _log("VALIDATION_ERROR", "self follow", actor=actor_user_id)
        return _err("VALIDATION_ERROR", "actor_user_id must not equal target_user_id", field="actor_user_id")

    users = _load("users.json"); users = users if isinstance(users, list) else []
    edges = _load("social_edges.json"); edges = edges if isinstance(edges, list) else []

    actor = next((u for u in users if isinstance(u, dict) and u.get("id") == actor_user_id), None)
    if not actor:
        _log("NOT_FOUND", "actor not found", actor=actor_user_id)
        return _err("NOT_FOUND", "Actor user not found", resource="users", id=actor_user_id)
    target = next((u for u in users if isinstance(u, dict) and u.get("id") == target_user_id), None)
    if not target:
        _log("NOT_FOUND", "target not found", actor=actor_user_id)
        return _err("NOT_FOUND", "Target user not found", resource="users", id=target_user_id)

    if actor.get("status") != "active":
        _log("UNAUTHORIZED", "actor not active", actor=actor_user_id)
        return _err("UNAUTHORIZED", "User is not allowed to perform this action", reason="user_not_active")
    if target.get("status") == "deleted":
        _log("CONFLICT", "target deleted", actor=actor_user_id)
        return _err("CONFLICT", "Cannot follow this user due to their current status", rule="target.status != 'deleted'")

    now = _now_iso()

    edge = None
    for e in edges:
        if not isinstance(e, dict):
            continue
        if e.get("edge_type") == "follow" and e.get("actor_user_id") == actor_user_id and e.get("target_user_id") == target_user_id:
            edge = e
            break

    if edge:
        if edge.get("status") == "active":
            _log("OK", "already following", actor=actor_user_id)
            return {"data": edge}
        # revoked -> active
        edge["status"] = "active"
        edge["updated_at"] = now
        _save("social_edges.json", edges)
        _log("OK", "reactivated", actor=actor_user_id)
        return {"data": edge}

    edge = {
        "id": _gen_id("edg"),
        "edge_type": "follow",
        "actor_user_id": actor_user_id,
        "target_user_id": target_user_id,
        "target_tweet_id": None,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    edges.append(edge)
    _save("social_edges.json", edges)
    _log("OK", "created", actor=actor_user_id)
    return {"data": edge}

def unfollow_user(actor_user_id, target_user_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    t0 = time.time()
    endpoint = "unfollow_user"
    now = _iso_now()

    def _log(status, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "rql_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "credential_used": credential_used,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    # ---- Rate limit (if configured) ----
    cfgs = _load("service_config.json")
    cfg = cfgs[0] if isinstance(cfgs, list) and cfgs else (cfgs if isinstance(cfgs, dict) else {})
    rl = None
    if isinstance(cfg, dict):
        rl = (cfg.get("rate_limits", {}) or {}).get(endpoint) or (cfg.get("rate_limits", {}) or {}).get("*")
    if isinstance(rl, dict):
        try:
            window_s = int(rl.get("window_seconds", 60))
            max_req = int(rl.get("max_requests", 120))
        except Exception:
            window_s, max_req = None, None
        if window_s and max_req is not None:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != endpoint:
                    continue
                dt = _parse_iso(r.get("created_at"))
                if dt is None:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= max_req:
                err = _err("RATE_LIMIT", "Rate limit exceeded.")
                _log("error", error_code=err["error"]["code"])
                return err

    # ---- Validation ----
    if not isinstance(actor_user_id, str) or not actor_user_id:
        err = _err("VALIDATION_ERROR", "actor_user_id must be a non-empty string.", field="actor_user_id")
        _log("error", error_code=err["error"]["code"])
        return err
    if not isinstance(target_user_id, str) or not target_user_id:
        err = _err("VALIDATION_ERROR", "target_user_id must be a non-empty string.", field="target_user_id")
        _log("error", error_code=err["error"]["code"])
        return err

    # Vendor schema shows a too-strict pattern (^usr_01H...), but datastore uses usr_01J...
    # Realistic validation: must look like our service's user id prefix.
    if not actor_user_id.startswith("usr_") or len(actor_user_id) < 8:
        err = _err("VALIDATION_ERROR", "actor_user_id is malformed (expected an id like 'usr_...').", field="actor_user_id")
        _log("error", error_code=err["error"]["code"])
        return err
    if not target_user_id.startswith("usr_") or len(target_user_id) < 8:
        err = _err("VALIDATION_ERROR", "target_user_id is malformed (expected an id like 'usr_...').", field="target_user_id")
        _log("error", error_code=err["error"]["code"])
        return err

    if actor_user_id == target_user_id:
        err = _err(
            "VALIDATION_ERROR",
            "actor_user_id must not equal target_user_id (business rule: cannot follow/unfollow self).",
            field="actor_user_id",
        )
        _log("error", error_code=err["error"]["code"])
        return err

    users = _load("users.json")
    if isinstance(users, dict) and "rows" in users and isinstance(users["rows"], list):
        users = users["rows"]
    if not isinstance(users, list):
        users = []

    actor = next((u for u in users if isinstance(u, dict) and u.get("id") == actor_user_id), None)
    target = next((u for u in users if isinstance(u, dict) and u.get("id") == target_user_id), None)
    if actor is None:
        err = _err("NOT_FOUND", "actor_user_id does not reference an existing user.", field="actor_user_id")
        _log("error", error_code=err["error"]["code"])
        return err
    if target is None:
        err = _err("NOT_FOUND", "target_user_id does not reference an existing user.", field="target_user_id")
        _log("error", error_code=err["error"]["code"])
        return err

    # Interactive actions require non-deleted user per constraints
    if actor.get("status") == "deleted" or actor.get("status") is None:
        err = _err("UNAUTHORIZED", "actor_user_id is not permitted to perform interactive actions (user is deleted).")
        _log("error", error_code=err["error"]["code"])
        return err
    if actor.get("status") == "suspended":
        err = _err("UNAUTHORIZED", "actor_user_id is not permitted to perform interactive actions (user is suspended).")
        _log("error", error_code=err["error"]["code"])
        return err

    edges = _load("social_edges.json")
    if isinstance(edges, dict) and "rows" in edges and isinstance(edges["rows"], list):
        edges = edges["rows"]
    if not isinstance(edges, list):
        edges = []

    edge = None
    for e in edges:
        if not isinstance(e, dict):
            continue
        if e.get("edge_type") == "follow" and e.get("actor_user_id") == actor_user_id and e.get("target_user_id") == target_user_id:
            edge = e
            break

    if edge is None:
        err = _err("CONFLICT", "No follow relationship exists to remove.", rule="follow edge must exist")
        _log("error", error_code=err["error"]["code"])
        return err

    status = edge.get("status")
    if status == "revoked":
        # idempotent unfollow
        _log("ok")
        return {
            "data": {
                "relationship": {
                    "edge_id": edge.get("id"),
                    "edge_type": "follow",
                    "actor_user_id": actor_user_id,
                    "target_user_id": target_user_id,
                    "status": "revoked",
                    "updated_at": edge.get("updated_at"),
                    "created_at": edge.get("created_at"),
                }
            }
        }

    if status != "active":
        err = _err("INVALID_TRANSITION", "Cannot unfollow from current edge status.", current=status, target="revoked")
        _log("error", error_code=err["error"]["code"])
        return err

    # Transition active -> revoked
    edge["status"] = "revoked"
    edge["updated_at"] = now
    _save("social_edges.json", edges)

    _log("ok")
    return {
        "data": {
            "relationship": {
                "edge_id": edge.get("id"),
                "edge_type": "follow",
                "actor_user_id": actor_user_id,
                "target_user_id": target_user_id,
                "status": "revoked",
                "updated_at": edge.get("updated_at"),
                "created_at": edge.get("created_at"),
            }
        }
    }

