def search_tweets(query, author_user_id=None, lang=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_tweets"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        log_row = {
            "id": "rql_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(log_row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfgs = _load("service_config.json")
        cfg = cfgs[0] if isinstance(cfgs, list) and cfgs else (cfgs if isinstance(cfgs, dict) else {})
        rl = cfg.get("rate_limits", {}).get(endpoint) or cfg.get("rate_limits", {}).get("*")
        if not rl:
            return None
        try:
            window_s = int(rl.get("window_seconds", 60))
            max_req = int(rl.get("max_requests", 300))
        except Exception:
            return None
        logs = _load("request_logs.json")
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s))
        cnt = 0
        for r in logs:
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff and r.get("endpoint") == endpoint:
                cnt += 1
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl_err = _rate_limit_check()
    if rl_err:
        _log("error", error_code=rl_err["error"]["code"])
        return rl_err

    if not isinstance(query, str) or len(query.strip()) < 1:
        e = _err("VALIDATION_ERROR", "query must be a non-empty string.", field="query")
        _log("error", error_code=e["error"]["code"])
        return e
    q = query.strip()

    usr_pat = re.compile(r"^usr_01H[0-9A-Z]{15,}$")
    if author_user_id is not None:
        if not isinstance(author_user_id, str) or not usr_pat.match(author_user_id):
            e = _err("VALIDATION_ERROR", "author_user_id is malformed.", field="author_user_id")
            _log("error", error_code=e["error"]["code"])
            return e

    if lang is not None:
        if not isinstance(lang, str) or len(lang.strip()) < 1:
            e = _err("VALIDATION_ERROR", "lang must be a non-empty string when provided.", field="lang")
            _log("error", error_code=e["error"]["code"])
            return e
        lang = lang.strip()

    if status is not None:
        if status not in ("published", "deleted", "hidden"):
            e = _err("VALIDATION_ERROR", "status is invalid.", field="status")
            _log("error", error_code=e["error"]["code"])
            return e

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
        _log("error", error_code=e["error"]["code"])
        return e

    if sort is None:
        sort = "created_at_desc"
    if sort not in ("created_at_desc", "created_at_asc"):
        e = _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
        _log("error", error_code=e["error"]["code"])
        return e

    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor.strip()) < 1:
            e = _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")
            _log("error", error_code=e["error"]["code"])
            return e
        c = cursor.strip()
        # Opaque cursor: base64url(JSON)
        try:
            padded = c + "=" * (-len(c) % 4)
            decoded = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            cursor_obj = json.loads(decoded)
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")
            _log("error", error_code=e["error"]["code"])
            return e
        if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1:
            e = _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")
            _log("error", error_code=e["error"]["code"])
            return e
        if cursor_obj.get("sort") not in ("created_at_desc", "created_at_asc"):
            e = _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")
            _log("error", error_code=e["error"]["code"])
            return e

    tweets = _load("tweets.json")
    entities = _load("tweet_entities.json")

    # If author filter supplied, ensure user exists (and not deleted for interactive visibility context)
    if author_user_id is not None:
        users = _load("users.json")
        u = next((x for x in users if x.get("id") == author_user_id), None)
        if not u:
            e = _err("NOT_FOUND", "author_user_id does not exist.", field="author_user_id")
            _log("error", error_code=e["error"]["code"])
            return e

    # default business rule for search: published only unless caller requests status
    eff_status = status if status is not None else "published"

    # Parse hashtags in query for entity match: #tag
    q_lower = q.lower()
    hash_tags = [m.group(1).lower() for m in re.finditer(r"(?:^|\s)#([A-Za-z0-9_]{1,100})\b", q)]
    hashtag_tweet_ids = set()
    if hash_tags:
        want = set(hash_tags)
        for ent in entities:
            if ent.get("entity_type") == "hashtag" and isinstance(ent.get("normalized_tag"), str) and ent.get("normalized_tag") in want:
                tid = ent.get("tweet_id")
                if isinstance(tid, str):
                    hashtag_tweet_ids.add(tid)

    # Candidate filter
    cands = []
    for tw in tweets:
        if eff_status is not None and tw.get("status") != eff_status:
            continue
        if author_user_id is not None and tw.get("author_user_id") != author_user_id:
            continue
        if lang is not None and tw.get("lang") != lang:
            continue

        txt = tw.get("text") or ""
        txt_l = txt.lower() if isinstance(txt, str) else ""
        text_match = (q_lower in txt_l) if q_lower else False
        hashtag_match = (tw.get("id") in hashtag_tweet_ids) if hashtag_tweet_ids else False

        # match either text or hashtag entities
        if not (text_match or hashtag_match):
            continue
        cands.append(tw)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    reverse = (sort == "created_at_desc")
    cands.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), r.get("id") or ""), reverse=reverse)

    # Apply cursor after sorting
    if cursor_obj is not None:
        if cursor_obj.get("sort") != sort:
            e = _err("VALIDATION_ERROR", "cursor does not match requested sort.", field="cursor")
            _log("error", error_code=e["error"]["code"])
            return e
        after_created_at = cursor_obj.get("after_created_at")
        after_id = cursor_obj.get("after_id")
        if not isinstance(after_created_at, str) or not isinstance(after_id, str):
            e = _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")
            _log("error", error_code=e["error"]["code"])
            return e
        after_dt = _parse_dt(after_created_at)
        if after_dt is None:
            e = _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")
            _log("error", error_code=e["error"]["code"])
            return e

        def is_after(row):
            rdt = _parse_dt(row.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            rid = row.get("id") or ""
            if reverse:
                # For desc: next page are items strictly "older" than (after_dt, after_id)
                return (rdt < after_dt) or (rdt == after_dt and rid < after_id)
            # asc: next page are items strictly "newer" than (after_dt, after_id)
            return (rdt > after_dt) or (rdt == after_dt and rid > after_id)

        cands = [r for r in cands if is_after(r)]

    total = len(cands)
    page = cands[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {
            "v": 1,
            "sort": sort,
            "after_created_at": last.get("created_at"),
            "after_id": last.get("id"),
        }
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    _log("ok")
    return {
        "tweets": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "status": eff_status,
        }
    }

def get_trending_topics(lang=None, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_trending_topics"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        log_row = {
            "id": "rql_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(log_row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfgs = _load("service_config.json")
        cfg = cfgs[0] if isinstance(cfgs, list) and cfgs else (cfgs if isinstance(cfgs, dict) else {})
        rl = cfg.get("rate_limits", {}).get(endpoint) or cfg.get("rate_limits", {}).get("*")
        if not rl:
            return None
        try:
            window_s = int(rl.get("window_seconds", 60))
            max_req = int(rl.get("max_requests", 60))
        except Exception:
            return None
        logs = _load("request_logs.json")
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s))
        cnt = 0
        for r in logs:
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff and r.get("endpoint") == endpoint:
                cnt += 1
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl_err = _rate_limit_check()
    if rl_err:
        _log("error", error_code=rl_err["error"]["code"])
        return rl_err

    if lang is not None:
        if not isinstance(lang, str) or len(lang.strip()) < 1:
            e = _err("VALIDATION_ERROR", "lang must be a non-empty string when provided.", field="lang")
            _log("error", error_code=e["error"]["code"])
            return e
        lang = lang.strip()

    if limit is None:
        limit = 10
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.", field="limit")
        _log("error", error_code=e["error"]["code"])
        return e

    tweets = _load("tweets.json")
    entities = _load("tweet_entities.json")

    # 24 hour window
    cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(hours=24)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    tweet_by_id = {t.get("id"): t for t in tweets if isinstance(t.get("id"), str)}
    counts = {}

    for ent in entities:
        if ent.get("entity_type") != "hashtag":
            continue
        tag = ent.get("normalized_tag")
        if not isinstance(tag, str) or not (1 <= len(tag) <= 100):
            continue
        tid = ent.get("tweet_id")
        tw = tweet_by_id.get(tid)
        if not tw:
            continue
        if tw.get("status") != "published":
            continue
        if lang is not None and tw.get("lang") != lang:
            continue
        dt = _parse_dt(tw.get("created_at"))
        if dt is None or dt < cutoff:
            continue
        counts[tag] = counts.get(tag, 0) + 1

    # order by count desc then tag asc for stability
    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    top = items[:limit]

    topics = [{"normalized_tag": tag, "count": cnt} for tag, cnt in top]

    _log("ok")
    return {
        "topics": topics,
        "meta": {
            "window_hours": 24,
            "lang": lang,
            "limit": limit,
            "returned": len(topics),
        }
    }

def create_list(owner_user_id, name, visibility, description=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_01J" + "".join(secrets.choice(alphabet) for _ in range(16))

    def _log(status, note=None, actor=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "create_list",
            "actor_user_id": actor,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "note": note
        })
        _save("request_logs.json", logs)

    t0 = time.time()

    if not isinstance(owner_user_id, str) or not re.match(r"^usr_01[0-9A-Z]{10,}$", owner_user_id):
        _log("VALIDATION_ERROR", "owner_user_id malformed")
        return _err("VALIDATION_ERROR", "owner_user_id is malformed", field="owner_user_id")
    if not isinstance(name, str) or len(name.strip()) < 1 or len(name) > 100:
        _log("VALIDATION_ERROR", "name invalid", actor=owner_user_id)
        return _err("VALIDATION_ERROR", "name is required and must be between 1 and 100 characters", field="name")
    if not isinstance(visibility, str) or visibility not in ("public", "private"):
        _log("VALIDATION_ERROR", "visibility invalid", actor=owner_user_id)
        return _err("VALIDATION_ERROR", "visibility must be one of: public, private", field="visibility")
    if description is not None and not isinstance(description, str):
        _log("VALIDATION_ERROR", "description invalid", actor=owner_user_id)
        return _err("VALIDATION_ERROR", "description must be a string", field="description")

    users = _load("users.json"); users = users if isinstance(users, list) else []
    owner = next((u for u in users if isinstance(u, dict) and u.get("id") == owner_user_id), None)
    if not owner:
        _log("NOT_FOUND", "owner not found", actor=owner_user_id)
        return _err("NOT_FOUND", "Owner user not found", resource="users", id=owner_user_id)
    if owner.get("status") != "active":
        _log("UNAUTHORIZED", "owner not active", actor=owner_user_id)
        return _err("UNAUTHORIZED", "User is not allowed to perform this action", reason="user_not_active")

    lists = _load("lists.json"); lists = lists if isinstance(lists, list) else []

    # uniqueness: unique(owner_user_id, name) where status != 'deleted'
    for l in lists:
        if not isinstance(l, dict):
            continue
        if l.get("owner_user_id") == owner_user_id and isinstance(l.get("name"), str) and l.get("name") == name and l.get("status") != "deleted":
            _log("CONFLICT", "duplicate list name", actor=owner_user_id)
            return _err("CONFLICT", "List name already exists for this owner", rule="unique(owner_user_id, name) where status != 'deleted'")

    # quota: <= 1000 non-deleted
    owned_active = 0
    for l in lists:
        if isinstance(l, dict) and l.get("owner_user_id") == owner_user_id and l.get("status") != "deleted":
            owned_active += 1
    if owned_active >= 1000:
        _log("QUOTA_EXCEEDED", "list quota exceeded", actor=owner_user_id)
        return _err("QUOTA_EXCEEDED", "Maximum lists per owner exceeded", limit=1000)

    now = _now_iso()
    row = {
        "id": _gen_id("lst"),
        "owner_user_id": owner_user_id,
        "name": name,
        "description": description,
        "visibility": visibility,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    lists.append(row)
    _save("lists.json", lists)

    _log("OK", "created", actor=owner_user_id)
    return {"data": row}

