    if not isinstance(member_user_id, str) or not re.match(r"^usr_01[0-9A-Z]{10,}$", member_user_id):
        _log("VALIDATION_ERROR", "member_user_id malformed")
        return _err("VALIDATION_ERROR", "member_user_id is malformed", field="member_user_id")
    if not isinstance(added_by_user_id, str) or not re.match(r"^usr_01[0-9A-Z]{10,}$", added_by_user_id):
        _log("VALIDATION_ERROR", "added_by_user_id malformed")
        return _err("VALIDATION_ERROR", "added_by_user_id is malformed", field="added_by_user_id")

    users = _load("users.json"); users = users if isinstance(users, list) else []
    lists = _load("lists.json"); lists = lists if isinstance(lists, list) else []
    members = _load("list_members.json"); members = members if isinstance(members, list) else []

    lst = next((l for l in lists if isinstance(l, dict) and l.get("id") == list_id), None)
    if not lst:
        _log("NOT_FOUND", "list not found", actor=added_by_user_id)
        return _err("NOT_FOUND", "List not found", resource="lists", id=list_id)
    if lst.get("status") == "deleted":
        _log("CONFLICT", "list deleted", actor=added_by_user_id)
        return _err("CONFLICT", "Cannot modify a deleted list", rule="lists.status != 'deleted'")

    added_by = next((u for u in users if isinstance(u, dict) and u.get("id") == added_by_user_id), None)
    if not added_by:
        _log("NOT_FOUND", "added_by user not found", actor=added_by_user_id)
        return _err("NOT_FOUND", "added_by_user_id not found", resource="users", id=added_by_user_id)
    member = next((u for u in users if isinstance(u, dict) and u.get("id") == member_user_id), None)
    if not member:
        _log("NOT_FOUND", "member user not found", actor=added_by_user_id)
        return _err("NOT_FOUND", "member_user_id not found", resource="users", id=member_user_id)

    if added_by.get("status") != "active":
        _log("UNAUTHORIZED", "adder not active", actor=added_by_user_id)
        return _err("UNAUTHORIZED", "User is not allowed to perform this action", reason="user_not_active")

    # Only owner may add members
    if lst.get("owner_user_id") != added_by_user_id:
        _log("UNAUTHORIZED", "not list owner", actor=added_by_user_id)
        return _err("UNAUTHORIZED", "Only the list owner may add members", rule="added_by_user_id must equal lists.owner_user_id")

    now = _now_iso()
    existing = next((m for m in members if isinstance(m, dict) and m.get("list_id") == list_id and m.get("member_user_id") == member_user_id), None)
    if existing:
