        # removed -> active
        existing["status"] = "active"
        existing["added_by_user_id"] = added_by_user_id  # keep most recent actor
        existing["updated_at"] = now
        _save("list_members.json", members)
        _log("OK", "reactivated", actor=added_by_user_id)
        return {"data": existing}

    row = {
        "id": _gen_id("mem"),
        "list_id": list_id,
        "member_user_id": member_user_id,
        "added_by_user_id": added_by_user_id,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    members.append(row)
    _save("list_members.json", members)

    _log("OK", "created", actor=added_by_user_id)
    return {"data": row}

