def get_owned_lists(owner_user_id, status=None, visibility=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0371000" if __import__("os").path.isdir("./environment_mix/0371000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _encode_cursor(payload):
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _log(status_code, note=None, actor=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "get_owned_lists",
            "actor_user_id": actor,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "note": note
        })
        _save("request_logs.json", logs)

    t0 = time.time()

    if not isinstance(owner_user_id, str) or not re.match(r"^usr_01[0-9A-Z]{10,}$", owner_user_id):
        _log("VALIDATION_ERROR", "owner_user_id malformed")
        return _err("VALIDATION_ERROR", "owner_user_id is malformed", field="owner_user_id")

    if status is not None and (not isinstance(status, str) or status not in ("active", "archived", "deleted")):
        _log("VALIDATION_ERROR", "bad status", actor=owner_user_id)
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")

    if visibility is not None and (not isinstance(visibility, str) or visibility not in ("public", "private")):
        _log("VALIDATION_ERROR", "bad visibility", actor=owner_user_id)
        return _err("VALIDATION_ERROR", "visibility must be one of: public, private", field="visibility")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR", "bad limit", actor=owner_user_id)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if sort is None:
        sort = "created_at_desc"
    if not isinstance(sort, str) or sort not in ("created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc"):
        _log("VALIDATION_ERROR", "bad sort", actor=owner_user_id)
        return _err("VALIDATION_ERROR", "sort must be one of: created_at_desc, created_at_asc, updated_at_desc, updated_at_asc", field="sort")

    cur = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("VALIDATION_ERROR", "bad cursor", actor=owner_user_id)
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        cur = _decode_cursor(cursor)
        if cur is None:
            _log("VALIDATION_ERROR", "cursor decode fail", actor=owner_user_id)
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    users = _load("users.json"); users = users if isinstance(users, list) else []
    if not any(isinstance(u, dict) and u.get("id") == owner_user_id for u in users):
        _log("NOT_FOUND", "owner not found", actor=owner_user_id)
        return _err("NOT_FOUND", "Owner user not found", resource="users", id=owner_user_id)

    lists = _load("lists.json"); lists = lists if isinstance(lists, list) else []

    # Business rule: status in ('active','archived') for get_owned_lists unless filtered explicitly to deleted.
    rows = []
    for l in lists:
        if not isinstance(l, dict):
            continue
        if l.get("owner_user_id") != owner_user_id:
            continue
        if status is None:
            if l.get("status") not in ("active", "archived"):
                continue
        else:
            if l.get("status") != status:
                continue
        if visibility is not None and l.get("visibility") != visibility:
            continue
        rows.append(l)

    if sort.startswith("created_at"):
        keyf = lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min)
    else:
        keyf = lambda r: (_parse_dt(r.get("updated_at")) or datetime.datetime.min)
    reverse = sort.endswith("_desc")
    rows.sort(key=keyf, reverse=reverse)

    start = 0
    if cur:
        if cur.get("u") != owner_user_id or not isinstance(cur.get("i"), int) or cur.get("i") < 0:
            _log("VALIDATION_ERROR", "cursor mismatch", actor=owner_user_id)
            return _err("VALIDATION_ERROR", "cursor does not match request", field="cursor")
        start = cur["i"]

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = _encode_cursor({"u": owner_user_id, "i": start + limit}) if has_more else None

    _log("OK", "ok", actor=owner_user_id)
    return {"data": page, "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
